function demoMain(idx,label){
  var srcs=["function alpha(){var x=1;} class Beta{method(){}}","const gamma=()=>{}; let delta=2; function eps(){}","class Zeta{constructor(){} render(){}} function theta(){}","var iota=1; function kappa(a,b){return a+b;}"];
  var src=srcs[idx%srcs.length]; var syms=[];
  var re=/(?:function\s+(\w+))|(?:class\s+(\w+))|(?:(?:const|let|var)\s+(\w+)\s*=)/g; var m;
  while((m=re.exec(src))!==null){syms.push(m[1]||m[2]||m[3]);}
  return "["+label+"] symbols in source: "+syms.join(", ")+" ("+syms.length+" found)";
}

